import json, sys, unittest
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
sys.path.insert(0,str(ROOT/'tools/asset-language'))
from lib.validation import validate_contract, validate_record

class ValidationTests(unittest.TestCase):
    def test_contract_passes(self): self.assertEqual(validate_contract(), [])
    def test_complete_record_passes(self):
        r={"contractVersion":1,"id":"example","displayName":"Example","representation":"plane","role":"surface_fixture","authoringSpace":"depth_tile","placementFrame":"surface_domain","materials":["old_limestone"],"states":["inactive","active"],"defaultState":"inactive","variants":[],"sockets":[],"sources":{},"products":{},"provenance":{"generator":"test","generatorVersion":"1","sourceCommit":"x","command":"test","inputs":[],"outputs":[]}}
        self.assertEqual(validate_record(r),[])
    def test_bad_default_state(self):
        r={"contractVersion":1,"id":"example","displayName":"Example","representation":"plane","role":"surface_fixture","authoringSpace":"depth_tile","placementFrame":"surface_domain","materials":[],"states":["active"],"defaultState":"inactive","variants":[],"sockets":[],"sources":{},"products":{},"provenance":{}}
        self.assertTrue(any(d['code']=='default_state' for d in validate_record(r)))
    def test_required_failure_matrix(self):
        base={"contractVersion":1,"id":"example","displayName":"Example","representation":"plane","role":"surface_fixture","authoringSpace":"depth_tile","placementFrame":"surface_domain","materials":["old_limestone"],"states":["inactive"],"defaultState":"inactive","variants":[],"sockets":[],"sources":{},"products":{},"provenance":{"generator":"g","generatorVersion":"1","sourceCommit":"c","command":"x","inputs":[],"outputs":[]}}
        cases=[("invalid record ID",lambda r:r.update(id="Bad"),"invalid_id"),("missing required field",lambda r:r.pop("displayName"),"missing_field"),("wrong top-level type",lambda r:r.update(sources=[]),"object_type"),("empty display name",lambda r:r.update(displayName=""),"invalid_id"),("duplicate material",lambda r:r.update(materials=["old_limestone","old_limestone"]),"duplicate_id"),("duplicate state",lambda r:r.update(states=["inactive","inactive"]),"duplicate_id"),("duplicate variant",lambda r:r.update(variants=["v","v"]),"duplicate_id"),("state variant overlap",lambda r:r.update(variants=["inactive"]),"state_variant_overlap"),("unknown material",lambda r:r.update(materials=["missing"]),"unknown_material"),("invalid space frame",lambda r:r.update(placementFrame="item_viewport"),"space_frame"),("invalid item display",lambda r:r.update(role="item_display"),"role_compatibility"),("invalid structural opening",lambda r:r.update(role="structural_opening"),"role_compatibility"),("absolute path",lambda r:r.update(sources={"prompt":"/x"}),"invalid_path"),("backslash path",lambda r:r.update(sources={"prompt":"a\\b"}),"invalid_path"),("parent escape path",lambda r:r.update(sources={"prompt":"../x"}),"invalid_path"),("duplicate socket",lambda r:r.update(sockets=[{"id":"x","kind":"vfx","position":[0,0,0]},{"id":"x","kind":"vfx","position":[0,0,0]}]),"duplicate_socket"),("non-object socket",lambda r:r.update(sockets=["x"]),"socket_type"),("missing socket position",lambda r:r.update(sockets=[{"id":"x","kind":"vfx"}]),"vector"),("unknown socket state",lambda r:r.update(sockets=[{"id":"x","kind":"vfx","position":[0,0,0],"state":"missing"}]),"socket_state"),("non-normalized vector",lambda r:r.update(sockets=[{"id":"x","kind":"vfx","position":[0,0,0],"forward":[2,0,0]}]),"vector_normalization"),("zero vector",lambda r:r.update(sockets=[{"id":"x","kind":"vfx","position":[0,0,0],"forward":[0,0,0]}]),"vector_normalization"),("parallel vectors",lambda r:r.update(sockets=[{"id":"x","kind":"vfx","position":[0,0,0],"forward":[1,0,0],"up":[1,0,0]}]),"parallel_vectors"),("non-object metric product",lambda r:r.update(products={"heightMetric":"x"}),"invalid_path"),("missing metric range",lambda r:r.update(products={"heightMetric":{"path":"h.png"}}),"range_cells"),("non-positive metric range",lambda r:r.update(products={"heightMetric":{"path":"h.png","rangeCells":0}}),"range_cells"),("metric guide collision",lambda r:r.update(products={"heightMetric":{"path":"h.png","rangeCells":1},"depthGuide":"h.png"}),"path_collision"),("guide legacy collision",lambda r:r.update(products={"depthGuide":"h.png","legacyHeight":"h.png"}),"path_collision"),("malformed SHA-256",lambda r:r.update(provenance={**base["provenance"],"inputs":[{"path":"x","sha256":"bad"}]}),"sha256"),("duplicate input",lambda r:r.update(provenance={**base["provenance"],"inputs":[{"path":"x"},{"path":"x"}]}),"duplicate_provenance_path"),("duplicate output",lambda r:r.update(provenance={**base["provenance"],"outputs":[{"path":"x"},{"path":"x"}]}),"duplicate_provenance_path"),("input output collision",lambda r:r.update(provenance={**base["provenance"],"inputs":[{"path":"x"}],"outputs":[{"path":"x"}]}),"duplicate_provenance_path"),("source output collision",lambda r:r.update(sources={"prompt":"x"},provenance={**base["provenance"],"outputs":[{"path":"x"}]}),"source_output_collision"),("missing provenance identity",lambda r:r.update(provenance={}),"provenance_field"),("wrong provenance collection type",lambda r:r.update(provenance={**base["provenance"],"inputs":{}}),"provenance_type")]
        for name, mutate, code in cases:
            with self.subTest(name=name):
                r=json.loads(json.dumps(base)); mutate(r)
                self.assertTrue(any(d['code']==code for d in validate_record(r)), name)
    def test_diagnostics_are_deterministically_ordered(self):
        r={"contractVersion":1,"id":"Bad","displayName":"","representation":"plane","role":"surface_fixture","authoringSpace":"depth_tile","placementFrame":"item_viewport","materials":["x","x"],"states":[],"defaultState":"x","variants":[],"sockets":[],"sources":[],"products":[],"provenance":[]}
        a=validate_record(r); b=validate_record(r); self.assertEqual(a,b); self.assertEqual(a,sorted(a,key=lambda d:(d['path'],d['field'],d['code'],d['message'])))
if __name__=='__main__': unittest.main()
